import{_ as a,o as c,c as h,a2 as t}from"./chunks/framework.62rcL0wY.js";const d=JSON.parse('{"title":"Quản lý cửa sổ","description":"","frontmatter":{},"headers":[],"relativePath":"bat-dau/quan-ly-cua-so.md","filePath":"bat-dau/quan-ly-cua-so.md"}'),i={name:"bat-dau/quan-ly-cua-so.md"};function o(e,n,s,l,r,u){return c(),h("div",null,[...n[0]||(n[0]=[t('<h1 id="quan-ly-cua-so" tabindex="-1">Quản lý cửa sổ <a class="header-anchor" href="#quan-ly-cua-so" aria-label="Permalink to &quot;Quản lý cửa sổ&quot;">​</a></h1><p>Trang này giới thiệu công cụ Quản lý cửa sổ (Window Manager) tích hợp trong Clickermann, giúp xem và khôi phục vị trí, kích thước cửa sổ ứng dụng cũng như xử lý các cửa sổ bị trong suốt.</p><div class="info custom-block"><p class="custom-block-title">Hình minh họa sẽ bổ sung</p><p>Hình chụp cửa sổ Quản lý cửa sổ (Window Manager) của Clickermann (với các thông số cửa sổ và ô chọn độ trong suốt Alpha) sẽ được bổ sung sau khi chụp trực tiếp trên máy Windows.</p></div><h2 id="hai-cong-dung-chinh-cua-quan-ly-cua-so" tabindex="-1">Hai công dụng chính của Quản lý cửa sổ <a class="header-anchor" href="#hai-cong-dung-chinh-cua-quan-ly-cua-so" aria-label="Permalink to &quot;Hai công dụng chính của Quản lý cửa sổ&quot;">​</a></h2><p>Công cụ Quản lý cửa sổ mang lại hai khả năng hữu ích khi viết script tự động hóa:</p><h3 id="xem-va-khoi-phuc-thong-so-cua-so" tabindex="-1">Xem và khôi phục thông số cửa sổ <a class="header-anchor" href="#xem-va-khoi-phuc-thong-so-cua-so" aria-label="Permalink to &quot;Xem và khôi phục thông số cửa sổ&quot;">​</a></h3><p>Khi làm việc với một ứng dụng không chạy toàn màn hình, không có gì đảm bảo ở lần mở tiếp theo cửa sổ đó sẽ nằm ở đúng vị trí cũ.</p><p>Nhờ công cụ Quản lý cửa sổ, bạn có thể dễ dàng xem được các thông số của bất kỳ cửa sổ nào và khôi phục lại các thông số đó khi cần thiết (từ bản v4.5.000, bạn có thể nhập tay mã <code>HWND</code> vào Quản lý cửa sổ).</p><p><strong>Suy luận:</strong> Ngoài thao tác thủ công trên cửa sổ công cụ này, bạn có thể kết hợp các lệnh <a href="/clickermann-guide-vi/lenh/winapi.html#wndpos"><code>WNDPOS</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#wndsize"><code>WNDSIZE</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#wndgetinfo"><code>WNDGETINFO</code></a> và <a href="/clickermann-guide-vi/lenh/winapi.html#wndsetinfo"><code>WNDSETINFO</code></a> ngay trong script để tự động cố định vị trí và kích thước cửa sổ trước khi bấm chuột.</p><h3 id="dat-do-trong-suot-alpha-de-clickermann-nhin-thay-cua-so" tabindex="-1">Đặt độ trong suốt (Alpha) để Clickermann nhìn thấy cửa sổ <a class="header-anchor" href="#dat-do-trong-suot-alpha-de-clickermann-nhin-thay-cua-so" aria-label="Permalink to &quot;Đặt độ trong suốt (Alpha) để Clickermann nhìn thấy cửa sổ&quot;">​</a></h3><p>Clickermann không nhìn thấy các cửa sổ trong suốt (alpha) — thay vì thấy cửa sổ đó, chương trình chỉ nhìn thấy những gì nằm phía dưới nó, dù vẫn có thể bấm chuột lên cửa sổ đó.</p><p>Trong công cụ Quản lý cửa sổ, bạn có thể đặt mức <strong>100% Alpha</strong> (theo ảnh trong help của bản cũ: chọn <strong>Alpha 100%</strong> ở ô chọn thả xuống rồi bấm nút áp dụng bên cạnh). Khi đó, cờ cửa sổ phân lớp được gỡ bỏ và cửa sổ trước đó bị trong suốt sẽ hiển thị đầy đủ cho cả Clickermann lẫn bạn.</p><hr><p><em>Nguồn: Tài liệu trợ giúp <code>help.chm</code> (bài Quản lý cửa sổ, FAQ và Lịch sử phiên bản).</em></p>',14)])])}const p=a(i,[["render",o]]);export{d as __pageData,p as default};
